CREATE OR REPLACE FUNCTION public.can_support_student(p_student uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'psychologist') AND EXISTS (SELECT 1 FROM public.student_data sd JOIN public.classrooms c ON c.id=sd.classroom_id JOIN public.classroom_members cm ON cm.classroom_id=c.id AND cm.student_id=sd.user_id WHERE sd.user_id=p_student AND c.psychologist_id=auth.uid() AND c.is_active)); $$;
REVOKE ALL ON FUNCTION public.can_support_student(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_support_student(uuid) TO authenticated,service_role;
ALTER TABLE public.alerts ADD COLUMN IF NOT EXISTS survey_response_id uuid REFERENCES public.survey_responses(id), ADD COLUMN IF NOT EXISTS message_id uuid REFERENCES public.messages(id);
CREATE UNIQUE INDEX IF NOT EXISTS alerts_survey_source_unique ON public.alerts(survey_response_id) WHERE survey_response_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS alerts_message_source_unique ON public.alerts(message_id) WHERE message_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS crisis_message_unique ON public.crisis_detections(message_id);
ALTER TABLE public.messages ADD COLUMN IF NOT EXISTS request_id uuid;
CREATE UNIQUE INDEX IF NOT EXISTS messages_request_unique ON public.messages(sender_id,request_id) WHERE request_id IS NOT NULL;
DO $$ DECLARE r record; BEGIN FOR r IN SELECT tablename,policyname FROM pg_policies WHERE schemaname='public' AND tablename IN ('alerts','crisis_detections','student_data','survey_responses','conversations','messages','psychologist_notes') LOOP EXECUTE format('DROP POLICY %I ON public.%I',r.policyname,r.tablename); END LOOP; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['alerts','crisis_detections','student_data','survey_responses','conversations','messages','psychologist_notes'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); END LOOP; END $$;
GRANT SELECT ON public.alerts,public.crisis_detections,public.student_data,public.survey_responses,public.conversations,public.messages,public.psychologist_notes TO authenticated;
GRANT ALL ON public.alerts,public.crisis_detections,public.student_data,public.survey_responses,public.conversations,public.messages,public.psychologist_notes TO service_role;
REVOKE ALL ON public.alerts,public.crisis_detections,public.student_data,public.survey_responses,public.conversations,public.messages,public.psychologist_notes FROM anon;
REVOKE INSERT,UPDATE,DELETE ON public.alerts,public.crisis_detections,public.student_data,public.survey_responses,public.conversations,public.messages FROM authenticated;
GRANT UPDATE(resolved) ON public.alerts TO authenticated;
GRANT UPDATE(reviewed,reviewed_by,reviewed_at) ON public.crisis_detections TO authenticated;
GRANT UPDATE(grade,class) ON public.student_data TO authenticated;
GRANT INSERT ON public.survey_responses TO authenticated;
GRANT UPDATE(title,status) ON public.conversations TO authenticated;
REVOKE INSERT ON public.classroom_members FROM authenticated,anon;
REVOKE UPDATE ON public.classrooms FROM authenticated;
GRANT UPDATE(name,description,join_code,is_active) ON public.classrooms TO authenticated;
CREATE POLICY safety_alert_select ON public.alerts FOR SELECT TO authenticated USING (public.can_support_student(student_id));
CREATE POLICY safety_alert_review ON public.alerts FOR UPDATE TO authenticated USING (public.can_support_student(student_id)) WITH CHECK (public.can_support_student(student_id));
CREATE POLICY safety_crisis_select ON public.crisis_detections FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND public.can_support_student(c.student_id)));
CREATE POLICY safety_crisis_review ON public.crisis_detections FOR UPDATE TO authenticated USING (EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND public.can_support_student(c.student_id))) WITH CHECK (EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND public.can_support_student(c.student_id)) AND reviewed_by=auth.uid());
CREATE POLICY safety_student_select ON public.student_data FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.can_support_student(user_id));
CREATE POLICY safety_student_update ON public.student_data FOR UPDATE TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE POLICY safety_response_select ON public.survey_responses FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.can_support_student(user_id));
CREATE POLICY safety_response_insert ON public.survey_responses FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND public.has_role(auth.uid(),'student'));
CREATE POLICY safety_conversation_select ON public.conversations FOR SELECT TO authenticated USING (student_id=auth.uid() OR public.can_support_student(student_id));
CREATE POLICY safety_conversation_update ON public.conversations FOR UPDATE TO authenticated USING (public.can_support_student(student_id)) WITH CHECK (public.can_support_student(student_id));
CREATE POLICY safety_message_select ON public.messages FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND (c.student_id=auth.uid() OR public.can_support_student(c.student_id))));
GRANT INSERT,UPDATE ON public.psychologist_notes TO authenticated;
CREATE POLICY safety_note_select ON public.psychologist_notes FOR SELECT TO authenticated USING (public.can_support_student(student_id));
CREATE POLICY safety_note_insert ON public.psychologist_notes FOR INSERT TO authenticated WITH CHECK (psychologist_id=auth.uid() AND public.can_support_student(student_id));
CREATE POLICY safety_note_update ON public.psychologist_notes FOR UPDATE TO authenticated USING (psychologist_id=auth.uid() AND public.can_support_student(student_id)) WITH CHECK (psychologist_id=auth.uid() AND public.can_support_student(student_id));
DROP POLICY IF EXISTS "Psychologists can view classroom students" ON public.profiles;
CREATE POLICY safety_profile_support_select ON public.profiles FOR SELECT TO authenticated USING (public.can_support_student(id));
DROP POLICY IF EXISTS "Psychologists can view crisis messages from their students" ON public.chat_messages;
CREATE POLICY safety_legacy_crisis_select ON public.chat_messages FOR SELECT TO authenticated USING (is_crisis AND public.can_support_student(user_id));